import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a create or update record trigger on incident table.

Flow(
    {
        $id: Now.ID['flow_trigger_create_or_update_record'],
        name: 'Flow - Trigger Create Or Update Record',
        description: 'Flow used by tests to validate create or update record trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.createdOrUpdated,
        { $id: Now.ID['trigger_create_or_update_record'], annotation: 'Trigger on incident create or update' },
        {
            table: 'incident',
            condition: 'priority=2',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
            trigger_strategy: 'once',
        }
    ),
    () => {
        // Empty body; this test focuses on trigger configuration only
    }
)
